/*  JustPlayMusic with the Sound Driver  A minimalist Mac Application that showcases the library files needed to play  a background .mid standard MIDI file.     Usage in your own project:  Do #include "muMIDIPlay.c" in your project, and that file will include the rest  Do #include "muSoundDriverMIDIDispatch.c" in your project which will include Sound Driver stuff as well      Step 1a: either have a .mid file in the same folder as the executable  Step 1b: or embed the .mid file in a 'smf ' raw data resource in your project's .rsrc file    Step 2: Use this every time you want to load a standard MIDI fileœ     prepMIDIFileForPlay("name of file"); //from a file in the same directory       or     prepMIDIResForPlay(resID); //from a 'smf ' resource embedded in your application  this will copy the content of the .mid into memory    Step 3: Once during your loop pass, do this:     midiLoopPass()  returns false if it's done playing. You can also check it with isMIDIDone()    Step 4: Do this to "rewind" the midi file at its beginning and start the playback over     rewindAndPlayMIDI();*///Includes#include "muMidiPlay.c"                //one-stop shop include#include "muSoundDriverMIDIDispatch.c" //so we can affect the Sound Driver in the output#include "HideMenuBar.c"               //very useful to tag along game projects#include "myWindow.c"                  //really simple window setup//Defines#define kEmbedded_Warcraft 128 //this is the 'smf ' ID for human2.mid embedded in a resource#define kEmbedded_Bach     129 //this is the 'smf ' ID for Bach's toccata & fugue in a resource//Functionsvoid main()	{	Boolean isPlaying = false; //very basic loop control for playback		myInitStuff(); //Mac Manager standard stuff	hideMenuBar(); //from HideMenuBar.c		/*********** * CHOICE #1* Select which window you want for this demo program***********/	//myWindow(true);       //if true, sets simple window with PICT	myWindow(false);		//if false, sets a white plain window with text instruction to quit   /***********/		setupMIDISerial(true); //must massage the serial port. true=modem, false=printer        //prepSWSynth();	prepFTWaves(); //prepare four-tone synth of the Sound Driver        prepDispatch();    //gCurSnd.gChoice = kSDSquare;	gCurSnd.ptrWave = &sawWave; //select the first instrument for FT  	gCurSnd.gChoice = kSDFourTone;		if(!SoundDone()) StopSound();	if(SoundDone()) StartSound(&myRec,256,nil);	resetFT();	/*	ftNoteSend(0x90, 0x3C, 0x7F, gCurSnd.ptrWave);	ftNoteSend(0x90, 0x3D, 0x7F, gCurSnd.ptrWave);	ftNoteSend(0x90, 0x3F, 0x7F, gCurSnd.ptrWave);	ftNoteSend(0x90, 0x42, 0x7F, gCurSnd.ptrWave);	*/	//printf("%02x %02x %02x %02x", gCurSnd.ptrWave[0], gCurSnd.ptrWave[1], 	//gCurSnd.ptrWave[2], gCurSnd.ptrWave[3]);	//printf("\n");	//while(!Button())	//	;		//showMenuBar(); //from HideMenuBar.c		//closeSerialDriver(); //must be done once at the end		//return;/*********** * CHOICE #2* Select which loading method for the midi data***********/	//prepMIDIResForPlay(kEmbedded_Bach);  //load from 'smf ' data resource embedded in this app	prepMIDIFileForPlay("\phuman2.mid");   //load from a file in the same dir as this app/***********/	isPlaying = true; //prepare the loop control	while(isPlaying) //main loop		{					//	if(midiLoopPass() == false)			if(midiLoopPassSoundDriver() == false) //if false, then no more MIDI events left to play			{			rewindAndPlayMIDI();			}			if(Button()) 			{			allNotesOff();				isPlaying = false; //one possible way to exit out of the loop			}		}	showMenuBar(); //from HideMenuBar.c		closeSerialDriver(); //must be done once at the end	StopSound();	}